use crate::decision::{ActionKind, OutcomeKind};
use crate::decision_runtime::ActionCandidate;
use crate::state::{ActiveTransformation, EnergyLedger, Environment, Organism, Simulation};
use std::collections::{HashMap, HashSet};

fn water_field_amount(environment:&Environment,organism:&Organism)->f64{organism.occupied_cells.first().and_then(|p|environment.field.index_for_position(p.x,p.y)).map(|i|environment.field.cells[i].materials.iter().flat_map(|m|m.parts.iter()).filter(|(n,_)|n=="Water").map(|(_,a)|*a).sum()).unwrap_or(0.0)}
fn break_net_energy(bond_energy:f64,interaction_energy:f64,work_cost:f64)->Option<f64>{if !bond_energy.is_finite()||bond_energy<0.0||!interaction_energy.is_finite()||!work_cost.is_finite()||work_cost<0.0{return None}let net=bond_energy+interaction_energy-work_cost;if net.is_finite(){Some(net)}else{None}}
fn settle_break_energy(organism:&mut Organism,bond:crate::structure::Bond,break_interaction_energy:f64,net:f64,work:f64,ledger:&mut EnergyLedger)->bool{if net<0.0&&organism.usable_energy+f64::EPSILON< -net{return false}if organism.structure.break_matching_bond(bond).is_none(){return false}organism.add_transaction_stress(work);if work>0.0{ledger.total_heat_dissipated+=work}organism.usable_energy+=net;if bond.bond_energy>0.0{ledger.total_potential_energy_released+=bond.bond_energy;}if break_interaction_energy>0.0{ledger.total_potential_energy_released+=break_interaction_energy;}if net>0.0{ledger.total_usable_energy_gained+=net;}true}

pub(crate) fn resolve_stress_break(organism:&mut Organism,environment:&Environment,ledger:&mut EnergyLedger)->bool{let Some((_,target))=organism.structure.bonds.iter().enumerate().min_by(|(_,a),(_,b)|a.strength.partial_cmp(&b.strength).unwrap_or(std::cmp::Ordering::Equal))else{return false};let target=*target;let Some(a)=organism.structure.units.get(target.unit_a).and_then(|u|u.properties(&environment.catalog))else{return false};let Some(b)=organism.structure.units.get(target.unit_b).and_then(|u|u.properties(&environment.catalog))else{return false};let work=break_work_cost(a,b,crate::math::complexity(2.0));if !work.is_finite()||work<0.0{return false}let Some(candidate)=crate::contact::connection_pair_candidates(&organism.structure,target.unit_a,target.unit_b,&environment.catalog).into_iter().find(|c|c.point_a==target.point_a&&c.point_b==target.point_b)else{return false};let formation_interaction=crate::combine::experimental_interaction(a,b,candidate,water_field_amount(environment,organism));let break_interaction_energy=-formation_interaction.signed_value;let Some(net)=break_net_energy(target.bond_energy,break_interaction_energy,work)else{return false};settle_break_energy(organism,target,break_interaction_energy,net,work,ledger)}

pub(crate) fn external_break_candidates(organism:&Organism,organisms:&[Organism],catalog:&[crate::resources::BaseResource])->Vec<ActionCandidate>{let mut candidates=Vec::new();for observation in &organism.resource_sense.sensed_organisms{let Some(target)=organisms.iter().find(|candidate|candidate.id==observation.id)else{continue};for bond in crate::contact::exposed_bonds_to_organism(organism,target,catalog,1e-9){candidates.push(ActionCandidate{action:ActionKind::Break,context_key:Some(format!("target:{}:{}:{}:{}:{}",target.id,bond.unit_a,bond.point_a,bond.unit_b,bond.point_b))});}}candidates}

fn parse_bond_context(key:&str)->Option<crate::structure::Bond>{let mut fields=key.strip_prefix("bond:")?.split(':').map(|value|value.parse::<usize>().ok());Some(crate::structure::Bond{unit_a:fields.next()??,point_a:fields.next()??,unit_b:fields.next()??,point_b:fields.next()??,strength:0.0,bond_energy:0.0})}
fn parse_external_break_context(key:&str)->Option<(String,crate::structure::Bond)>{let rest=key.strip_prefix("target:")?;let mut parts=rest.splitn(2,':');let target_id=parts.next()?.to_owned();let bond=parse_bond_context(&format!("bond:{}",parts.next()?))?;Some((target_id,bond))}
fn record_break_outcome(organism:&mut Organism,context:Option<String>,net:f64){let outcome=if net>f64::EPSILON{OutcomeKind::Beneficial}else if net< -f64::EPSILON{OutcomeKind::Harmful}else{OutcomeKind::Neutral};let candidate=ActionCandidate{action:ActionKind::Break,context_key:context};crate::decision_runtime::record_outcome(&mut organism.decision_history,&candidate,outcome);if net>0.0{let reinforcement=(net*organism.genome.memory_strength()).clamp(0.0,1.0);let(x,y)=organism.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));reinforce_memory_point(organism,x,y,reinforcement)}}
fn release_detached_components(initiator:&mut Organism,target:&mut Organism,environment:&mut Environment,root_component:&[usize])->bool{let root_set:HashSet<usize>=root_component.iter().copied().collect();let body=crate::organism_geometry::OrganismBodyGeometry::from_structure(&initiator.structure,&environment.catalog);let mut old_to_new=HashMap::new();let mut new_units=Vec::with_capacity(root_component.len());for &old_index in root_component{let Some(unit)=target.structure.units.get(old_index)else{return false};old_to_new.insert(old_index,new_units.len());new_units.push(unit.clone());}let mut new_structure=crate::structure::OrganismStructure::new();new_structure.units=new_units;for bond in &target.structure.bonds{if root_set.contains(&bond.unit_a)&&root_set.contains(&bond.unit_b){let Some(&unit_a)=old_to_new.get(&bond.unit_a)else{return false};let Some(&unit_b)=old_to_new.get(&bond.unit_b)else{return false};let mut retained=*bond;retained.unit_a=unit_a;retained.unit_b=unit_b;new_structure.bonds.push(retained);}}for(index,unit)in target.structure.units.iter().enumerate(){if root_set.contains(&index){continue}let material=unit.material.material().clone();if let Some(ref body)=body{if body.contains_point(unit.placement.x,unit.placement.y)&&initiator.store_material(material.clone()){continue}}environment.field.deposit(unit.placement.x,unit.placement.y,material);}target.structure=new_structure;true}
fn resolve_external_break(transformation:&ActiveTransformation,initiator:&mut Organism,target:&mut Organism,environment:&mut Environment,ledger:&mut EnergyLedger)->Option<f64>{let actual=transformation.bond.and_then(|bond|target.structure.bonds.iter().find(|candidate|candidate.has_same_identity(&bond)).copied())?;if !crate::contact::exposed_bonds_to_organism(initiator,target,&environment.catalog,1e-9).iter().any(|bond|bond.has_same_identity(&actual)){return None}let a=target.structure.units.get(actual.unit_a)?.properties(&environment.catalog)?;let b=target.structure.units.get(actual.unit_b)?.properties(&environment.catalog)?;let candidate=crate::contact::connection_pair_candidates(&target.structure,actual.unit_a,actual.unit_b,&environment.catalog).into_iter().find(|c|c.point_a==actual.point_a&&c.point_b==actual.point_b)?;let work=break_work_cost(a,b,transformation.complexity);if !work.is_finite()||work<0.0{return None}let formation_interaction=crate::combine::experimental_interaction(a,b,candidate,water_field_amount(environment,target));let break_interaction_energy=-formation_interaction.signed_value;let net=break_net_energy(actual.bond_energy,break_interaction_energy,work)?;if net<0.0&&initiator.usable_energy+f64::EPSILON< -net{return None}target.structure.break_matching_bond(actual)?;target.add_transaction_stress(work);if work>0.0{ledger.total_heat_dissipated+=work}initiator.usable_energy+=net;if actual.bond_energy>0.0{ledger.total_potential_energy_released+=actual.bond_energy;}if break_interaction_energy>0.0{ledger.total_potential_energy_released+=break_interaction_energy;}if net>0.0{ledger.total_usable_energy_gained+=net;}let components=target.structure.connected_components();let root=components.iter().find(|component|component.contains(&0))?.clone();if !release_detached_components(initiator,target,environment,&root){return None}Some(net)}

impl Simulation {
 pub(crate) fn try_start_transformation(organism:&mut Organism,catalog:&[crate::resources::BaseResource],next_id:&mut u64,decision:&ActionCandidate,organisms:&[Organism])->Option<ActiveTransformation>{if decision.action!=ActionKind::Break||organism.active_transformation_id.is_some(){return None}let key=decision.context_key.as_deref()?;let(computed_bond,target_organism_id)=if let Some((target_id,bond))=parse_external_break_context(key){let target=organisms.iter().find(|candidate|candidate.id==target_id)?;if target.id==organism.id{return None}if !crate::contact::exposed_bonds_to_organism(organism,target,catalog,1e-9).iter().any(|exposed|exposed.has_same_identity(&bond)){return None}(bond,Some(target_id))}else{(parse_bond_context(key)?,None)};let bond=if let Some(target_id)=&target_organism_id{let target=organisms.iter().find(|candidate|&candidate.id==target_id)?;target.structure.bonds.iter().find(|bond|bond.has_same_identity(&computed_bond)).copied()?}else{organism.structure.bonds.iter().find(|bond|bond.has_same_identity(&computed_bond)).copied()?};if !bond.bond_energy.is_finite()||bond.bond_energy<0.0{return None}let owner=if let Some(target_id)=&target_organism_id{organisms.iter().find(|candidate|&candidate.id==target_id)?}else{organism};let a=owner.structure.units.get(bond.unit_a)?.properties(catalog)?;let b=owner.structure.units.get(bond.unit_b)?.properties(catalog)?;let complexity=crate::math::complexity(2.0);let _work=break_work_cost(a,b,complexity);let duration=1_u64.max(complexity.ceil() as u64);let t=ActiveTransformation{id:*next_id,organism_id:organism.id.clone(),kind:crate::state::TransformationKind::Break,material:crate::resources::Material::free_base("",0.0),bond:Some(bond),target_organism_id,complexity,duration_ticks:duration,remaining_ticks:duration,decision_context_key:decision.context_key.clone()};*next_id+=1;organism.active_transformation_id=Some(t.id);Some(t)}
 pub(crate) fn resolve_transformation(transformation:&ActiveTransformation,organisms:&mut [Organism],environment:&mut Environment,ledger:&mut EnergyLedger){let Some(initiator_index)=organisms.iter().position(|o|o.id==transformation.organism_id)else{return};if let Some(target_id)=&transformation.target_organism_id{let Some(target_index)=organisms.iter().position(|o|&o.id==target_id)else{if let Some(initiator)=organisms.get_mut(initiator_index){initiator.active_transformation_id=None;let candidate=ActionCandidate{action:ActionKind::Break,context_key:transformation.decision_context_key.clone()};crate::decision_runtime::record_outcome(&mut initiator.decision_history,&candidate,OutcomeKind::Harmful);}return};if initiator_index==target_index{return}let(initiator,target)=if initiator_index<target_index{let(left,right)=organisms.split_at_mut(target_index);(&mut left[initiator_index],&mut right[0])}else{let(left,right)=organisms.split_at_mut(initiator_index);(&mut right[0],&mut left[target_index])};let result=resolve_external_break(transformation,initiator,target,environment,ledger);initiator.active_transformation_id=None;let candidate=ActionCandidate{action:ActionKind::Break,context_key:transformation.decision_context_key.clone()};crate::decision_runtime::record_outcome(&mut initiator.decision_history,&candidate,result.map_or(OutcomeKind::Harmful,|net|if net>f64::EPSILON{OutcomeKind::Beneficial}else if net< -f64::EPSILON{OutcomeKind::Harmful}else{OutcomeKind::Neutral}));if let Some(net)=result{if net>0.0{let reinforcement=(net*initiator.genome.memory_strength()).clamp(0.0,1.0);let(x,y)=initiator.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));reinforce_memory_point(initiator,x,y,reinforcement);}}return}let Some(target)=transformation.bond else{return};let Some(organism)=organisms.get_mut(initiator_index)else{return};if target.unit_a>=organism.structure.units.len()||target.unit_b>=organism.structure.units.len(){organism.active_transformation_id=None;return}if !organism.structure.bonds.iter().any(|b|b.has_same_identity(&target)){organism.active_transformation_id=None;return}let a=match organism.structure.units[target.unit_a].properties(&environment.catalog){Some(x)=>x,None=>{organism.active_transformation_id=None;return}};let b=match organism.structure.units[target.unit_b].properties(&environment.catalog){Some(x)=>x,None=>{organism.active_transformation_id=None;return}};let work=break_work_cost(a,b,transformation.complexity);if !work.is_finite()||work<0.0{organism.active_transformation_id=None;return}let candidate=match crate::contact::connection_pair_candidates(&organism.structure,target.unit_a,target.unit_b,&environment.catalog).into_iter().find(|c|c.point_a==target.point_a&&c.point_b==target.point_b){Some(x)=>x,None=>{organism.active_transformation_id=None;return}};let formation_interaction=crate::combine::experimental_interaction(a,b,candidate,water_field_amount(environment,organism));let break_interaction_energy=-formation_interaction.signed_value;let net=match break_net_energy(target.bond_energy,break_interaction_energy,work){Some(x)=>x,None=>{organism.active_transformation_id=None;return}};if net<0.0&&organism.usable_energy+f64::EPSILON< -net{organism.active_transformation_id=None;let candidate=ActionCandidate{action:ActionKind::Break,context_key:transformation.decision_context_key.clone()};crate::decision_runtime::record_outcome(&mut organism.decision_history,&candidate,OutcomeKind::Harmful);return}if organism.structure.break_matching_bond(target).is_none(){organism.active_transformation_id=None;return}organism.add_transaction_stress(work);if work>0.0{ledger.total_heat_dissipated+=work}organism.usable_energy+=net;if target.bond_energy>0.0{ledger.total_potential_energy_released+=target.bond_energy;}if break_interaction_energy>0.0{ledger.total_potential_energy_released+=break_interaction_energy;}if net>0.0{ledger.total_usable_energy_gained+=net;}organism.active_transformation_id=None;record_break_outcome(organism,transformation.decision_context_key.clone(),net)}
}
pub(crate) fn break_work_cost(a:crate::resources::ResourceProperties,b:crate::resources::ResourceProperties,complexity:f64)->f64{crate::combine::bond_strength(a,b)*complexity.max(0.0)}
pub(crate) fn reinforce_memory_point(organism:&mut Organism,x:f64,y:f64,reinforcement:f64){if let Some(point)=organism.memory.iter_mut().find(|p|(p.x-x).abs()<f64::EPSILON&&(p.y-y).abs()<f64::EPSILON){point.strength=crate::math::clamp01(point.strength+reinforcement)}else{organism.memory.push(crate::state::MemoryPoint{x,y,strength:crate::math::clamp01(reinforcement)})}}
#[cfg(test)]mod tests{use super::*;#[test]fn break_net_energy_supports_all_three_signs(){assert!(break_net_energy(10.0,5.0,3.0).unwrap()>0.0);assert_eq!(break_net_energy(10.0,0.0,10.0).unwrap(),0.0);assert!(break_net_energy(10.0,-5.0,6.0).unwrap()<0.0)}#[test]fn invalid_break_energy_is_rejected(){assert!(break_net_energy(-1.0,0.0,1.0).is_none());assert!(break_net_energy(1.0,f64::NAN,1.0).is_none());assert!(break_net_energy(1.0,0.0,-1.0).is_none())}#[test]fn bond_context_round_trips_identity(){let key="bond:2:3:5:7";let identity=parse_bond_context(key).unwrap();assert_eq!((identity.unit_a,identity.point_a,identity.unit_b,identity.point_b),(2,3,5,7));}#[test]fn external_context_round_trips_target(){let key="target:7:0:1:2:3";let(parsed,bond)=parse_external_break_context(key).unwrap();assert_eq!(parsed,"7");assert_eq!((bond.unit_a,bond.point_a,bond.unit_b,bond.point_b),(0,1,2,3));}}